// Test mới với WireMock: cổng thanh toán trả lời sau 1,5 giây
@RegisterExtension
static WireMockExtension gateway = WireMockExtension.newInstance()
        .options(wireMockConfig().dynamicPort()).build();

@Test
void slowGatewayIsRetriedSafely() throws Exception {
    gateway.stubFor(post("/payments")
            .willReturn(okJson("{\"status\":\"PAID\"}").withFixedDelay(1500)));
    PaymentClient client = new PaymentClient(gateway.baseUrl());

    assertThrows(HttpTimeoutException.class, () -> client.charge("ORD-42", 500_000));

    gateway.findAll(postRequestedFor(urlEqualTo("/payments")))
            .forEach(r -> System.out.println("POST /payments Idempotency-Key=" + r.getHeader("Idempotency-Key")));
    gateway.verify(1, postRequestedFor(urlEqualTo("/payments")));
}

