@Test
void retriesReuseTheSameIdempotencyKey() {
    gateway.stubFor(post("/payments")
            .willReturn(okJson("{\"status\":\"PAID\"}").withFixedDelay(1500)));

    assertThrows(HttpTimeoutException.class,
            () -> new PaymentClient(gateway.baseUrl()).charge("ORD-42", 500_000));

